export const BULK_FROM = 100
export const BULK_DISCOUNT = 0.05

/** The price of `qty` units of an item, in whole cents, rounded to the nearest cent. */
export function priceFor(item, qty) {
  const base = item.price * qty
  return Math.round(qty >= BULK_FROM ? base * (1 - BULK_DISCOUNT) : base)
}

input.new_string:
/** Bulk discounts, largest first: from how many units, and the share taken off. */
export const BULK = Object.freeze([
  { from: 200, discount: 0.1 },
  { from: 50, discount: 0.05 },
])

/** The price of `qty` units of an item, in whole cents, rounded to the nearest cent. */
export function priceFor(item, qty) {
  const base = item.price * qty
  const tier = BULK.find((entry) => qty >= entry.from)
  return Math.round(tier ? base * (1 - tier.discount) : base)
}

