input.new_string:
/** The items that run out within the low-stock window, fewest days left first (ties by SKU), each with its whole days left. */
export function lowStockReport(items, config = {}) {
  const window = config.lowStockDays ?? LOW_STOCK_DAYS
  return items
    .filter((item) => daysLeft(item) < window)
    .sort((a, b) => daysLeft(a) - daysLeft(b) || a.sku.localeCompare(b.sku))

