/** A field as the spreadsheet reads it: quoted, with its quotes doubled, when it holds a semicolon, a quote or a line break. */
function field(value) {
  const text = String(value)
  return /[;"\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
}

/** A header row, then one row per item: SKU, name, units on hand, price in cents, separated by semicolons. */
export function exportCsv(items) {
  const rows = [['sku', 'name', 'on_hand', 'price'], ...items.map((item) => [item.sku, item.name, item.onHand, item.price])]
  return rows.map((row) => row.map(field).join(';')).join('\n') + '\n'
}
